var canJump = function(nums) {
    let maxReach = 0;
    const n = nums.length;
    for (let i = 0; i < n; ++i) {
        if (i > maxReach) return false;
        const reach = i + nums[i];
        if (reach > maxReach) maxReach = reach;
        if (maxReach >= n - 1) return true;
    }
    return true;
};
